import React from "react";
import {
  FaClone,
  FaPercentage,
  FaFolderOpen,
  FaChevronLeft,
} from "react-icons/fa";
import Loader from "../common/Loader";
import withRouter from "../common/withRouter";

const API_URL = "https://iranaserviceapp.ir/test/api";

class SettleRequestPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      submitting: false,
      message: "",
      imageFile: null,
      imagePreview: "",
      card: null,
    };

    this.fileInputRef = React.createRef();

    this.handleBack = this.handleBack.bind(this);
    this.handleChooseFile = this.handleChooseFile.bind(this);
    this.handleFileChange = this.handleFileChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  componentDidMount() {
    try {
      const rawCard = localStorage.getItem("card");

      if (rawCard) {
        this.setState({
          card: JSON.parse(rawCard),
        });
      }
    } catch (error) {
      console.error("CARD PARSE ERROR:", error);
    }

    this.getRequestDetail();
  }

  getRequestDetail = () => {
    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
    });

    fetch(
      `${API_URL}/detail?id=${encodeURIComponent(id)}`,
      {
        method: "GET",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${token}`,
        },
      }
    )
      .then((response) => response.json())
      .then((data) => {
        console.log("REQUEST DETAIL API:", data);

        this.setState({
          request: data.request || null,
          clear: data.clear || null,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET REQUEST DETAIL ERROR:", error);

        this.setState({
          loading: false,
          message: "دریافت اطلاعات درخواست انجام نشد.",
        });
      });
  };

  handleBack() {
    this.props.navigate(-1);
  }

  handleChooseFile() {
    if (this.fileInputRef.current) {
      this.fileInputRef.current.click();
    }
  }

  handleFileChange(e) {
    const file =
      e.target.files && e.target.files[0];

    if (!file) {
      return;
    }

    const reader = new FileReader();

    reader.onload = () => {
      this.setState({
        imageFile: file,
        imagePreview: reader.result,
        message: "",
      });
    };

    reader.readAsDataURL(file);
  }

  handleSubmit(e) {
    e.preventDefault();

    const {
      request,
      imageFile,
    } = this.state;

    const token = localStorage.getItem("token");

    if (!request) {
      this.setState({
        message: "اطلاعات درخواست پیدا نشد.",
      });

      return;
    }

    if (!imageFile) {
      this.setState({
        message: "لطفاً عکس فیش واریزی را انتخاب کنید.",
      });

      return;
    }

    const totalReceived = Number(
      request.sum || 0
    );

    const suppliesCost = Number(
      request.abzar || 0
    );

    const totalFee =
      totalReceived - suppliesCost;

    const commissionAmount =
      totalFee / 2;

    const formData = new FormData();

    formData.append(
      "text1",
      request.code || ""
    );

    formData.append(
      "sum",
      commissionAmount
    );

    formData.append(
      "file1",
      imageFile
    );

    formData.append("desc", "");
    formData.append("text2", "");
    formData.append("text3", "");

    this.setState({
      submitting: true,
      message: "",
    });

    fetch(`${API_URL}/clear`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: formData,
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("CLEAR POST API:", data);

        if (String(data.status) === "1") {
          this.props.navigate(
            `/requests/history/${request.id}`
          );

          return;
        }

        this.setState({
          submitting: false,
          message:
            data.message ||
            "ثبت تسویه انجام نشد.",
        });
      })
      .catch((error) => {
        console.error(
          "CLEAR POST ERROR:",
          error
        );

        this.setState({
          submitting: false,
          message:
            "ارتباط با سرور برقرار نشد.",
        });
      });
  }

  render() {
    const {
      request,
      loading,
      submitting,
      message,
      imagePreview,
      card,
    } = this.state;

    if (loading) {
      return <Loader />;
    }

    if (!request) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            درخواست پیدا نشد.
          </div>
        </div>
      );
    }

    const totalReceived = Number(
      request.sum || 0
    );

    const suppliesCost = Number(
      request.abzar || 0
    );

    const totalFee =
      totalReceived - suppliesCost;

    const commissionAmount =
      totalFee / 2;

    return (
      <div dir="rtl">
        {submitting && <Loader />}

        <div className="container px-3 pt-4 pb-5">
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft size={14} />
            </button>
          </div>

          {card && (
            <div className="border rounded-4 p-4 mb-4 bg-white">
              <div className="d-flex align-items-center justify-content-between mb-3">
                <FaClone
                  className="text-primary"
                  size={22}
                />

                <span className="text-dark">
                  شماره کارت واریزی:
                </span>
              </div>

              <div
                className="text-center fw-bold fs-4 mb-3"
                style={{
                  letterSpacing: 2,
                }}
              >
                {card.number}
              </div>

              <div className="text-end text-muted">
                {card.name} / {card.bank}
              </div>
            </div>
          )}


          <form onSubmit={this.handleSubmit}>
            <div className="mb-3">
              <div className="text-muted small text-end mb-1">
                کد درخواست
              </div>

              <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 bg-white">
                <span className="text-muted">
                  {request.code}
                </span>

                <FaClone
                  className="text-secondary"
                  size={18}
                />
              </div>
            </div>

            <div className="mb-1">
              <div className="text-muted small text-end mb-1">
                پورسانت شرکت (%50)
              </div>

              <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 bg-white">
                <span className="text-muted">
                  {commissionAmount.toLocaleString(
                    "fa-IR"
                  )}{" "}
                  تومان
                </span>

                <FaPercentage
                  className="text-secondary"
                  size={18}
                />
              </div>
            </div>

            <div className="text-muted small text-end mb-3">
              مبلغ به تومان وارد شود
            </div>

            <div className="mb-4">
              <div className="text-muted small text-end mb-2">
                عکس فیش واریزی
              </div>

              <div className="border rounded-4 p-3 d-flex align-items-start justify-content-between gap-3">
                <div
                  className="rounded-3 bg-light flex-shrink-0"
                  style={{
                    width: "56%",
                    aspectRatio: "16 / 10",
                    backgroundImage: imagePreview
                      ? `url(${imagePreview})`
                      : "none",
                    backgroundSize: "cover",
                    backgroundPosition:
                      "center",
                  }}
                />

                <button
                  type="button"
                  onClick={
                    this.handleChooseFile
                  }
                  className="btn btn-outline-primary rounded-pill d-flex align-items-center gap-2 px-3 py-2"
                >
                  <span>
                    انتخاب فایل
                  </span>

                  <FaFolderOpen size={16} />
                </button>

                <input
                  ref={this.fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={
                    this.handleFileChange
                  }
                  className="d-none"
                />
              </div>
            </div>

            {message && (
              <div className="text-center text-danger small mb-3">
                {message}
              </div>
            )}

            <button
              type="submit"
              className="btn btn-primary w-100 rounded-3 py-3"
              disabled={submitting}
            >
              ثبت
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default withRouter(SettleRequestPage);
